$manifest = Get-Content .manifest.json -Raw | ConvertFrom-Json
$ingestedFiles = $manifest.PSObject.Properties.Name

# Lista todos os arquivos atuais em _raw/
$rawFiles = Get-ChildItem _raw | Select-Object -ExpandProperty Name

# Compara e deleta os que já estão no manifesto
foreach ($file in $rawFiles) {
    if ($ingestedFiles -contains $file) {
        Write-Host "Deletando rascunho já processado: $file"
        Remove-Item "_raw/$file"
    }
}

