args.command:
$files = Get-ChildItem _raw | Select-Object -ExpandProperty Name
$groups = @{
    "Motores e Pipeline (v1_, v2_, v3_, v4_, v5_, v6_)" = $files | Where-Object { $_ -match "^v\d" }
    "Walkthroughs e Run Reports" = $files | Where-Object { $_ -match "^(walkthrough_|run_report_)" }
    "Sessões (session_*)" = $files | Where-Object { $_ -match "^session_" }
    "Conceitos e Feedbacks (concept_claude_*)" = $files | Where-Object { $_ -match "^concept_claude_" }
    "Documentação Técnica e Projetos" = $files | Where-Object { $_ -notmatch "^(v\d|walkthrough_|run_report_|session_|concept_claude_)" }
}

foreach ($key in $groups.Keys) {
    Write-Host "--- Grupo: $key (${groups[$key].Count} arquivos) ---"
    $groups[$key] | Select-Object -First 10 | ForEach-Object { Write-Host " - $_" }
    if ($groups[$key].Count -gt 10) { Write-Host "   (e mais ...)" }
}

